/* Lot 112: var() invalid at computed-value time is unset for every property (generated by scripts/lot112_gen.py; expectations from scripts/lot112_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[2048];
static char g_a[4096], g_b[4096], g_r[16384];

/* the node lines of the report and the style attributes of #o and #i */
static void facts(const char *css, char *out, int cap) {
    int i, n = 0;
    char *p, *e;
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><p id=i>i</p></div></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    out[0] = 0;
    for (i = 0; i < g_d.nnodes; i++) {
        char s[512];
        s[0] = 0;
        wf_site_style_attr(&g_d, g_d.node[i].start, s, (int)sizeof(s));
        n += snprintf(out + n, (size_t)(cap - n), "%d:%s|", i, s);
    }
    TEST_ASSERT_TRUE(wf_site_report(&g_d, g_r, (int)sizeof(g_r)) > 0);
    for (p = g_r; (p = strstr(p, "node ")) != 0 && n < cap - 1; p = e) {
        e = strchr(p, '\n');
        if (!e) e = p + strlen(p);
        n += snprintf(out + n, (size_t)(cap - n), "%.*s|", (int)(e - p), p);
    }
}

/* the sheet with var() and the sheet as the model reads it agree */
static void same(const char *with_var, const char *as_read) {
    facts(with_var, g_a, (int)sizeof(g_a));
    facts(as_read, g_b, (int)sizeof(g_b));
    TEST_ASSERT_EQUAL_STRING(g_b, g_a);
}

static void test_l112_unset_0(void) {
    same("#o { --x: italic; font-style: italic } #i { font-style: var(--x, var(--y)) }", "#o { --x: italic; font-style: italic } #i { font-style: italic }");
    same("#i { text-transform: var(--z) }", "#i { text-transform: unset }");
    same("#o { visibility: hidden } #i { visibility: hidden; visibility: var(--x) }", "#o { visibility: hidden } #i { visibility: hidden; visibility: unset }");
    same("#o { --x: nosuch; background-color: #203040 } #i { --y: 12px; background-color: #00ff00; background-color: var(--x, var(--y)) }", "#o { --x: nosuch; background-color: #203040 } #i { --y: 12px; background-color: #00ff00; background-color: unset }");
    same("#o { --x: underline; text-decoration: underline } #i { --y: line-through; text-decoration: underline; text-decoration: var(--y) }", "#o { --x: underline; text-decoration: underline } #i { --y: line-through; text-decoration: underline; text-decoration: line-through }");
    same("#o { --x: blink2 } #i { text-decoration: underline; text-decoration: var(--x) }", "#o { --x: blink2 } #i { text-decoration: underline; text-decoration: unset }");
    same("#o { --x: italic } #i { font-style: italic; font-style: var(--z, italic) }", "#o { --x: italic } #i { font-style: italic; font-style: italic }");
    same("#o { --x: lowercase } #i { text-transform: uppercase; text-transform: var(--x) }", "#o { --x: lowercase } #i { text-transform: uppercase; text-transform: lowercase }");
    same("#o { --x: 12px; text-transform: uppercase } #i { --y: lowercase; text-transform: capitalize; text-transform: var(--z) }", "#o { --x: 12px; text-transform: uppercase } #i { --y: lowercase; text-transform: capitalize; text-transform: unset }");
    same("#o { --x: none } #i { display: inline; display: var(--z) }", "#o { --x: none } #i { display: inline; display: unset }");
}

